import{_ as a,C as s,o as e,c as n,a2 as l,b as i,w as o,a as d,E,a3 as g}from"./chunks/framework.BBdhqAg0.js";const A="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNkYAAAAAYAAjCB0C8AAAAASUVORK5CYII=",b=JSON.parse('{"title":"수수료 정산 관리","description":"","frontmatter":{},"headers":[],"relativePath":"sales/settlement.md","filePath":"sales/settlement.md","lastUpdated":1793125015000}'),C={name:"sales/settlement.md"};function B(c,t,h,u,_,f){const r=s("Mermaid");return e(),n("div",null,[t[1]||(t[1]=l('<h1 id="수수료-정산-관리" tabindex="-1">수수료 정산 관리 <a class="header-anchor" href="#수수료-정산-관리" aria-label="Permalink to &quot;수수료 정산 관리&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">📸 실제 화면 안내</p><p><img src="'+A+'" alt="수수료 정산 회차 및 개인별 명세 화면"><em>관리자 참고: 해당 화면의 실제 캡처 이미지를 <code>./images/settlement.png</code> 경로에 등록해 주세요.</em></p></div><blockquote><p><strong>수수료 정산 관리</strong>는 프로젝트의 정산 회차(월별/주기별)를 생성하고, 대상 기간 동안 체결된 유효 계약 실적과 수수료 정책을 매칭하여 개인별 인센티브 산출, 미정산 환수금 자동 상계, 그리고 3.3% 사업소득 원천세를 공제한 세후 실지급액을 확정하는 정산 엔진 모듈입니다.</p></blockquote><ul><li><strong>접근 경로</strong>: 시스템 좌측 내비게이션 메뉴에서 **[PJT 관리 시스템] → [분양 대행 관리] → [수수료 정산 관리]**를 선택하여 접속합니다.</li></ul>',4)),(e(),i(g,null,{default:o(()=>[E(r,{id:"mermaid-20",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5B%221.%20%EC%A0%95%EC%82%B0%20%ED%9A%8C%EC%B0%A8%20%EC%83%9D%EC%84%B1%3Cbr%3E(%EC%A7%91%EA%B3%84%20%EA%B8%B0%EA%B0%84%C2%B7%EC%A7%80%EA%B8%89%20%EC%98%88%EC%A0%95%EC%9D%BC%20%EC%84%A4%EC%A0%95)%22%5D%20--%3E%20B%5B%222.%20%EC%88%98%EC%88%98%EB%A3%8C%20%EC%9E%90%EB%8F%99%20%EC%A0%95%EC%82%B0%20%EC%8B%A4%ED%96%89%3Cbr%3E(%EC%9C%A0%ED%9A%A8%20%EA%B3%84%EC%95%BD%20%EC%A7%91%EA%B3%84%20%26%20%EC%A7%81%EC%B1%85%EB%B3%84%20R%EA%B0%92%20%EC%82%B0%EC%B6%9C)%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%223.%20%EA%B3%B5%EC%A0%9C%20%EB%B0%8F%20%EC%84%B8%EA%B8%88%20%EA%B3%84%EC%82%B0%3Cbr%3E(%EB%AF%B8%EC%A0%95%EC%82%B0%20%ED%99%98%EC%88%98%EA%B8%88%20%EC%83%81%EA%B3%84%20%26%203.3%25%20%EC%9B%90%EC%B2%9C%EC%84%B8%20%EA%B3%B5%EC%A0%9C)%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%224.%20%EA%B0%9C%EC%9D%B8%EB%B3%84%20%EB%AA%85%EC%84%B8%20%EA%B2%80%ED%86%A0%3Cbr%3E(%EA%B3%84%EC%A2%8C%C2%B7%EA%B3%84%EC%95%BD%20%EA%B1%B4%EB%B3%84%20%EC%88%98%EB%8B%B9%20%EB%8C%80%EC%A1%B0)%22%5D%0A%20%20%20%20D%20--%3E%20E%5B%22%E2%9C%85%20%EC%A0%95%EC%82%B0%20%ED%99%95%EC%A0%95%20(Confirm)%3Cbr%3E(%EC%88%98%EC%88%98%EB%A3%8C%20%EC%A7%80%EA%B8%89%20%EA%B4%80%EB%A6%AC%20%ED%99%94%EB%A9%B4%EC%9C%BC%EB%A1%9C%20%EC%9E%90%EB%8F%99%20%EC%9D%B4%EA%B4%80)%22%5D%0A"})]),fallback:o(()=>[...t[0]||(t[0]=[d(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=l('<h2 id="_1-개요-및-정산-엔진-특징" tabindex="-1">1. 개요 및 정산 엔진 특징 <a class="header-anchor" href="#_1-개요-및-정산-엔진-특징" aria-label="Permalink to &quot;1. 개요 및 정산 엔진 특징&quot;">​</a></h2><p>분양 대행사 및 영업 상담사에게 지급할 수수료를 주기별(예: 매월 말일 또는 격주 단위)로 집계하고 확정하는 종합 정산 엔진을 제공합니다.</p><ul><li><strong>직책별 차등 수수료(R값) 산출</strong>: 상담사 인센티브 외에도 소속 팀장, 본부장의 오버라이딩 수당을 직급 체계에 맞춰 자동 계산합니다. (팀장 공석 시 상위 본부장 합산 배정 또는 대행사 귀속 지원)</li><li><strong>미정산 환수금 자동 상계</strong>: 과거 계약 해약 등으로 발생한 환수금(<code>Clawback</code>)이 존재할 경우, 이번 회차 수수료에서 자동으로 차감 상계하여 회사의 채권 손실을 방지합니다.</li><li><strong>법정 3.3% 원천세 자동 계산</strong>: 프리랜서 사업소득세 3% 및 지방소득세 0.3%를 국세청 표준 원단위 절사 방식으로 자동 계산하여 세후 실지급액을 도출합니다.</li></ul><h2 id="_2-주요-기능" tabindex="-1">2. 주요 기능 <a class="header-anchor" href="#_2-주요-기능" aria-label="Permalink to &quot;2. 주요 기능&quot;">​</a></h2><ul><li><strong>정산 회차 생성 및 관리</strong>: 대상 기간(시작일~종료일), 지급 예정일, 회차명을 설정하여 회차 단위 관리</li><li><strong>수수료 자동 정산 실행</strong>: 버튼 클릭 한 번으로 대상 기간 내 승인 계약을 전수 집계하고 직책별 수당 및 세액 일괄 계산</li><li><strong>정산 내역 최종 확정</strong>: 검토가 완료된 정산 내역을 &#39;정산 확정&#39; 상태로 변경하여 <a href="/sales/payout.html">수수료 지급 관리</a> 단계로 이관</li><li><strong>개인별 상세 정산 내역 조회</strong>: 팝업창을 통해 상담사별 계약 건별 수수료 산출 근거 및 금융 계좌 정보 대조</li></ul><h2 id="_3-화면-구성-및-조작-가이드" tabindex="-1">3. 화면 구성 및 조작 가이드 <a class="header-anchor" href="#_3-화면-구성-및-조작-가이드" aria-label="Permalink to &quot;3. 화면 구성 및 조작 가이드&quot;">​</a></h2><h3 id="_1-회차-선택-및-제어-툴바" tabindex="-1">1. 회차 선택 및 제어 툴바 <a class="header-anchor" href="#_1-회차-선택-및-제어-툴바" aria-label="Permalink to &quot;1. 회차 선택 및 제어 툴바&quot;">​</a></h3><ul><li><strong>정산 회차 선택 드롭다운</strong>: 조회 및 정산 작업을 진행할 대상 회차 선택</li><li><strong>회차 상태 배지</strong>: 현재 회차의 진행 상태 표시 (<code>정산 작성 중</code>, <code>정산 확정</code>, <code>지급 완료</code>)</li><li><strong>[신규 회차 생성] 버튼</strong>: 새로운 정산 주기 회차를 개설하는 팝업 호출</li><li><strong>[수수료 자동 정산 실행] 버튼</strong>: 대상 기간 실적을 기반으로 정산 엔진을 일괄 가동</li><li><strong>[정산 확정] 버튼</strong>: 작성이 완료된 정산 내역을 최종 승인 및 확정 처리</li></ul><h3 id="_2-정산-총괄-요약-카드" tabindex="-1">2. 정산 총괄 요약 카드 <a class="header-anchor" href="#_2-정산-총괄-요약-카드" aria-label="Permalink to &quot;2. 정산 총괄 요약 카드&quot;">​</a></h3><p>선택된 회차의 전체 재무 집계 지표를 실시간 요약 카드로 제공합니다.</p><ul><li><strong>정산 계약 건수</strong>: 해당 회차에 포함되어 정산된 총 계약 건수</li><li><strong>총 지급액 (세전)</strong>: 직책별 인센티브 합계 + 기본급/일비 - 환수 공제액</li><li><strong>원천징수 세액 (3.3%)</strong>: 사업소득세(3%) + 지방소득세(0.3%) 합계</li><li><strong>총 실지급액 (세후)</strong>: 세전 총액에서 원천세를 차감한 실제 은행 이체 대상 총액</li></ul><h3 id="_3-개인별-정산-및-세금-공제-명세-테이블" tabindex="-1">3. 개인별 정산 및 세금 공제 명세 테이블 <a class="header-anchor" href="#_3-개인별-정산-및-세금-공제-명세-테이블" aria-label="Permalink to &quot;3. 개인별 정산 및 세금 공제 명세 테이블&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">항목</th><th style="text-align:left;">상세 설명 및 실무 기준</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>소속 팀 / 직책 / 성명</strong></td><td style="text-align:left;">영업 인력의 기본 인적 정보 (성명 클릭 시 상세 모달 팝업)</td></tr><tr><td style="text-align:left;"><strong>건수</strong></td><td style="text-align:left;">해당 인력에게 배정된 정산 대상 계약 건수</td></tr><tr><td style="text-align:left;"><strong>인센티브</strong></td><td style="text-align:left;">건당 수수료 정책에 의해 계산된 성과 수수료 합계</td></tr><tr><td style="text-align:left;"><strong>기본급 / 일비</strong></td><td style="text-align:left;">기본 지급액 또는 일비 보조금 (해당 시 표출)</td></tr><tr><td style="text-align:left;"><strong>공제 / 환수</strong></td><td style="text-align:left;">과거 해약 등으로 발생한 미정산 환수금 상계 차감액</td></tr><tr><td style="text-align:left;"><strong>총액 (세전)</strong></td><td style="text-align:left;">세전 지급 총액 (<code>인센티브 + 기본급 - 환수액</code>)</td></tr><tr><td style="text-align:left;"><strong>원천세 (3.3%)</strong></td><td style="text-align:left;">사업소득세(3%) + 지방소득세(0.3%) 합계 (10원 단위 절사)</td></tr><tr><td style="text-align:left;"><strong>실지급액 (세후)</strong></td><td style="text-align:left;">금융기관을 통해 실제 이체될 최종 세후 지급 금액</td></tr><tr><td style="text-align:left;"><strong>상태</strong></td><td style="text-align:left;">지급 진행 상태 (<code>지급대기</code>, <code>지급승인</code>, <code>지급완료</code>, <code>지급보류</code>)</td></tr><tr><td style="text-align:left;"><strong>상세</strong></td><td style="text-align:left;"><code>[보기]</code> 버튼 클릭 시 계약 건별 산출 근거 팝업 호출</td></tr></tbody></table><h3 id="_4-정산-회차-생성-팝업" tabindex="-1">4. 정산 회차 생성 팝업 <a class="header-anchor" href="#_4-정산-회차-생성-팝업" aria-label="Permalink to &quot;4. 정산 회차 생성 팝업&quot;">​</a></h3><p>새로운 정산 주기를 시작하기 위한 기본 설정 팝업창입니다:</p><ul><li><strong>정산 회차명</strong> (필수): 예: &quot;2026년 10월 1회차 분양 수수료 정산&quot;</li><li><strong>정산 대상 시작일 / 종료일</strong> (필수): 실적을 집계할 계약 체결일 범위 지정</li><li><strong>지급 예정일</strong> (선택): 금융 이체 예정 일자 지정</li><li><strong>정산 상태</strong> (필수): 신규 생성 시 기본값 <code>정산 작성 중</code></li></ul><h3 id="_5-개인별-수수료-정산-상세-팝업" tabindex="-1">5. 개인별 수수료 정산 상세 팝업 <a class="header-anchor" href="#_5-개인별-수수료-정산-상세-팝업" aria-label="Permalink to &quot;5. 개인별 수수료 정산 상세 팝업&quot;">​</a></h3><p>특정 영업 인력의 행에서 <strong><code>[보기]</code></strong> 버튼을 클릭하면 나타나는 상세 증빙 창입니다:</p><ul><li><strong>기본 인적사항 및 계좌 정보</strong>: 성명, 직책, 소속 팀, 입금 은행명, 계좌번호, 예금주</li><li><strong>금액 산출 구성</strong>: 인센티브 합계, 기본급, 공제/환수액 상세</li><li><strong>원천세 계산표</strong>: 세전총액, 사업소득세, 지방소득세, 원천징수 합계, 세후 실지급액</li><li><strong>정산 대상 계약 상세 목록</strong>: 계약 일련번호, 계약자명, 수당 구분(상담사/팀장/본부장), 건당 수수료 금액</li></ul><h2 id="_4-신입사원을-위한-실무-가이드" tabindex="-1">4. 신입사원을 위한 실무 가이드 <a class="header-anchor" href="#_4-신입사원을-위한-실무-가이드" aria-label="Permalink to &quot;4. 신입사원을 위한 실무 가이드&quot;">​</a></h2><ul><li><strong>💡 정산 확정 전 데이터 재검증 요령</strong>: <ul><li><code>[수수료 자동 정산 실행]</code> 버튼을 누른 후, 개인별 명세 테이블에서 **총액(세전)**과 **실지급액(세후)**을 대조하십시오.</li><li>특히 환수 대상자(계약 해약자)의 경우 과거 해약 건이 정상적으로 차감 반영되었는지 확인한 뒤 <strong><code>[정산 확정]</code></strong> 버튼을 눌러야 합니다.</li></ul></li><li><strong>💡 정산 확정 후 수정이 필요한 경우</strong>: <ul><li>이미 정산 확정된 회차는 데이터 무결성을 위해 임의 수정이 잠깁니다. 수정이 불가피한 경우 최고 관리자 권한을 통해 상태를 <code>정산 작성 중</code>으로 되돌린 후 재정산을 실행해야 합니다.</li></ul></li></ul>',21))])}const x=a(C,[["render",B]]);export{b as __pageData,x as default};
